from pathlib import Path
import json

AREA=Path(__file__).resolve().parents[1]/'swe_context'
PAPER='https://arxiv.org/html/2610.27377v1'
BENCH='https://github.com/jiayuanz3/SWEContextBench/tree/12ad6ab14e18e9378e1e293c9edbc3f7ce43d27b'


def read():
    return json.loads((AREA/'results.json').read_text(encoding='utf8'))


def pvalue(w,probability):
    return '< 0,001' if probability < .001 else w.dec(probability,3)


def cover_context():
    d=read()
    s=d['groups']['lite']['scores']
    return (f"На SWE-ContextBench Lite модель выбрала связанную прошлую траекторию для {s['qwen_1']} из 99 задач. "
            f"Поиск BM25 по тем же сохранённым записям дал {s['bm25_flat_1']}, авторы REM опубликовали 68. "
            "Гибридный Recall в авторской реализации дал 58. Если для каждого вопроса выбирать последнюю опубликованную связь, у нашего метода 73 попадания. Влияние выбранного опыта на исправление программы проверяется отдельно.")


def add_context(w):
    d=read();lite=d['groups']['lite'];n=lite['n'];s=lite['scores']
    w.page('SWE-ContextBench Lite  /  Что сохранять и какую запись читать','Один выбор из 300 прошлых задач',
           'У каждой новой ошибки есть опубликованная связь с прошлой задачей. До открытия разметки мы сформировали записи из публичных историй работы, проранжировали их и сохранили контрольные суммы всех решений.')
    w.p('В момент записи извлекаются три наблюдения. Первое — как пользователь описывал прежнюю ошибку. Второе — последнее открытое пояснение агента. Третье — пути и идентификаторы из фактически вызванных операций редактирования. Последнее поле подтверждает попытку изменения. Корректность старого исправления оно само по себе не гарантирует.')
    w.p('Для следующей задачи на вход поступало только её описание. Идентификаторы issue, явные ссылки, хеши коммитов и служебные поля исключались по фиксированным правилам. Текст задачи и финальное объяснение индексировались отдельно. Ранги лексического и семантического поиска объединялись. Qwen получала те же пять кандидатов, порядок показа определял хеш. Ей разрешалось выбрать одного.')
    w.tbl(['На всех 99 задачах','Верный первый','Эталон среди пяти'],[
        ['Только описание прежней ошибки, BM25',str(s['bm25_symptom_1']),str(s['bm25_symptom_5'])],
        ['Только объяснение и правки, BM25',str(s['bm25_outcome_1']),str(s['bm25_outcome_5'])],
        ['Три поля одной строкой, BM25',str(s['bm25_flat_1']),str(s['bm25_flat_5'])],
        ['Три поля одной строкой, Contriever',str(s['dense_flat_1']),str(s['dense_flat_5'])],
        ['Раздельные поля, только лексика',str(s['sparse_fields_1']),str(s['sparse_fields_5'])],
        ['Раздельные поля, смешанный поиск',str(s['fusion_1']),str(s['fusion_5'])],
        ['Те же 5, MiniLM-L12',str(s['minilm_1']),str(s['minilm_5'])],
        ['Те же 5, Qwen3.8-27B',str(s['qwen_1']),str(s['fusion_5'])],
        *[[name,str(s[key+'_1']),str(s[key+'_5'])] for key,name in [('recall_keyword','Recall 0.5.0, авторский лексический поиск'),('recall_hybrid','Recall 0.5.0, авторский гибридный поиск')] if key in d['author_controls']],
        ['REM, опубликованный результат','68','78']],[9.45,3.8,3.85],True)
    w.p(f"Среди 300 файлов обнаружено {d['unique_source_issue_ids']} разных исходных задач. В архиве нашлась хотя бы одна эталонная траектория для {lite['available']}/{n} вопросов. Все {n} вошли в знаменатель. При разборе одного исторического файла пропущена одна повреждённая строка. Раскладка всех выданных позиций и ответ каждого из 99 вызовов приложены.",'Caption')
    w.source('Chen и др., REM, таблица 1 и приложение D',PAPER)
    w.source('Zhu и др., данные SWE-ContextBench и исходные траектории',BENCH)
    w.page('SWE-ContextBench Lite  /  Сильные контроли и перенос','Сколько выигрыша даёт дополнительное чтение',
           'Число исправленных и испорченных решений показывает, когда модель действительно использовала доступ к пяти записям.')
    pairs=d['pairwise']['lite']
    matrix=[]
    for key,label in [('bm25_flat','BM25 по общей записи'),('bm25_symptom','BM25 по прошлой жалобе'),('fusion','Автоматический выбор первой'),('minilm','MiniLM-L12 по тем же пяти')]:
        r=pairs[key]
        matrix.append([label,str(r['wins'])+' / '+str(r['losses']),w.pp(r['delta'],1),w.pp(r['repo_ci95'][0],1)+' … '+w.pp(r['repo_ci95'][1],1),pvalue(w,r['mcnemar_p'])])
    for key in d['author_controls']:
        r=pairs[key]
        matrix.append([key.replace('recall_','Recall '),str(r['wins'])+' / '+str(r['losses']),w.pp(r['delta'],1),w.pp(r['repo_ci95'][0],1)+' … '+w.pp(r['repo_ci95'][1],1),pvalue(w,r['mcnemar_p'])])
    w.tbl(['С чем сравнили Qwen','Лучше / хуже','Δ, п. п.','95% ДИ, п. п.','p'],matrix,[6,2.8,2.45,3.65,2.2],True)
    w.p('Интервал получен повторной выборкой репозиториев. Парный точный тест Мак-Немара по задачам приведён как описание сравнений. Зависимость задач одного проекта и множественность контролей ограничивают его интерпретацию.')
    cost=d['llm_cost'];sizes=d['storage']
    w.p(f"Корпус исходных журналов занимает {w.dec(sizes['input_raw_bytes']/1e6,2)} МБ, извлечённый текст — {w.dec(sizes['record_text_bytes']/1e6,2)} МБ, в среднем {w.dec(sizes['avg_words'],0)} слов на запись. Стоимость однократного выбора на 99 вопросах составила {w.n(cost['input'])} входных и {w.n(cost['output'])} выходных токенов. В {cost['fallback']} случаях применилось резервное правило выбора первой записи. Это расходы извлечения, без бюджета последующей работы над кодом.")
    w.p('В REM автоматически извлечённые документы удалось создать для 267 из 300 траекторий; восемь запросов потеряли доступ к подходящему документу. У нас доступны 300. Опубликованное сравнение 68/99 использует Titan и другой reranker. Для исполнения программ авторы REM использовали вручную заданную схему записи, показавшую 66/99 при поиске. Парные предсказания REM не найдены. Разность с опубликованным числом объединяет покрытие, схему записи и выбор модели.')
    ext=d['groups']['extension']
    text=(f"За пределами Lite те же записи и замороженный ранжировщик применены ещё к {ext['n']} описаниям. В доступной библиотеке нашлись эталоны лишь для {ext['available']}. ")
    if 'extension_available' in d['groups']:
        ex=d['groups']['extension_available'];ss=ex['scores']
        text+=f"На этой условной выборке смешанный поиск нашёл {ss['fusion_1']}/{ex['n']}, BM25 — {ss['bm25_flat_1']}/{ex['n']}. "
    w.p(text+'Этот срез зависит от состава публичных исходных траекторий. Qwen на расширении не запускалась.','Caption')
    w.source('Публичная версия базы отношений и постановки задач','https://huggingface.co/datasets/jiayuanz3/SWEContextBench')
    w.page('SWE-ContextBench Lite  /  Проверка сопоставимости','Что означает результат 75 из 99',
           'Три задачи в публичной таблице имеют по две связанные прошлые задачи. Способ разрешать такие связи влияет на сравнение с REM.')
    sensitivity=json.loads((AREA/'gold_sensitivity.json').read_text(encoding='utf8'))
    w.tbl(['Правило сопоставления','Верный первый','В библиотеке'],[
        ['Любая указанная авторами связь, как в коде Recall',str(sensitivity['any']['match1'])+'/99',str(sensitivity['any']['in_library'])+'/99'],
        ['Только первая связь в зафиксированном parquet',str(sensitivity['first_in_dated_release']['match1'])+'/99',str(sensitivity['first_in_dated_release']['in_library'])+'/99'],
        ['Только последняя связь в том же порядке',str(sensitivity['last_in_dated_release']['match1'])+'/99',str(sensitivity['last_in_dated_release']['in_library'])+'/99'],
        ['Только задачи с единственной связью','73/96','96/96']], [9.2,4,3.9],True)
    w.p('Авторы REM сообщают, что в исходной библиотеке отсутствуют две размеченные траектории. У нас последняя запись в таблице связей воспроизводит именно этот потолок 97 из 99. Это правдоподобная реконструкция. Установить использованный авторами способ без их таблицы на уровне задач не удалось. Даже если выбрать по одной связи произвольным образом, наш результат лежит между 73 и 75. На общей шкале разница с опубликованными 68 составляет от пяти до семи задач.')
    w.p('При 73 и 68 успехах лучший возможный двусторонний p точного парного теста равен 0,0625, даже если каждый новый успех исправляет прежний промах. При 75 и 68 возможный p по одним маргинальным суммам лежит от 0,0156 до 0,419. Другой источник неопределённости — восемь недоступных в REM целевых записей. Без их идентификаторов нельзя приписать разницу методу записи или ранжирования.')
    w.p('Проверка одного и того же кода сопоставления на воспроизведённом Recall дала 53/99 для лексики и 58/99 для гибридного поиска. Эти числа совпадают с опубликованными округлёнными 53,5% и 58,6%. В сравнении с гибридным поиском у нашего метода 21 выигрыш и 4 потери. Эффект +17,17 п. п., 95% интервал по репозиториям от +11,66 до +30,61. На Django и SymPy приходится 62 из 99 задач. Преимущество сильнее обосновано для состава этого теста, чем для произвольного нового проекта.')
    w.source('Recall 0.5.0, авторские сравнительные результаты','https://github.com/alirng/recall/blob/585d0e21553d20e353588b9278e067d641a8283a/docs/benchmarks.md')
    w.source('REM, недостающие записи и режим reranking',PAPER+'#A4')

